/* @autogenerated */
import { EnvironmentProviders, makeEnvironmentProviders } from '@angular/core';
import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { provideOidcIdentity } from '@shared/context/identity/oidc-identity/oidc-identity.provider';
import { stepUpInterceptor } from '@shared/context/identity/oidc-identity/step-up.interceptor';

/**
 * Conector REST: los repositorios llaman a la API del backend con el token de la identidad OIDC.
 * Cada conector (rest, appwrite, firebase) trae su propio `provideConnector()`.
 */
export function provideConnector(): EnvironmentProviders {
  return makeEnvironmentProviders([provideHttpClient(withInterceptors([stepUpInterceptor])), provideOidcIdentity()]);
}
